programs.haiku:
"""Experimental-design vocabulary of scientific papers, figure and table references, and the
closing braces that end code blocks.

The component writes "this is an experiment report" into the residual stream. It is largest on
words for the parts of an experiment (control, sample, treatment, group, study, mice, Figure/Table
references); it grows the longer the text has been about experiments; and it is about 0.46 on a
closing brace that ends a line of code. Its value on everything else is 0."""

READS = ()

# Figure and table references, as in "(Figure 2)", "Fig. 3", "Table 1"
FIGURE_REFS = {"Fig", "Figure", "fig", "figure", "Table", "table", "Supplementary"}

# Words for an experiment's parts and subjects
HIGH = {" control", " controls", " Control", " sample", " samples", " Sample", " mice",
        " experimental", " experiment", " experiments"}
MID = {" study", " studies", " Study", " group", " groups", " treatment", " treatments", " treated",
       " untreated", " rats", " rat", " mouse", " participants", " subjects", " respectively",
       " compounds", " compound", " wild", " absence", " presence", " comparison", " panel", " healthy"}
LOW = {" data", " results", " methods", " method", " cells", " individuals", " tissues", " tissue",
       " reference", " values", " materials", " Methods", " Results", " ±", "±", " significantly"}

# Closing braces at the end of a line of code
CLOSING_BRACE = {" }", "}\n", " }\n", "}\n\n", " }\n\n", "}\r\n", " }\r\n", "}\r\n\r\n", "}\n\n\n",
                 " }\n\n\n", "};\n", " };\n", "};", " };", " },", "},\n", " },\n", "});\n"}

# "control" in software senses (version control, flow control) is not an experiment
SOFTWARE_CONTROL_BEFORE = {" version", " flow", " remote", " quality", " access", " mission"}

WORDS = FIGURE_REFS | HIGH | MID | LOW
DECAY = 0.95        # how fast the experiment-context count fades, per token
MAX_CONTEXT = 5.0   # cap on that count


def step(carry, prefix, upstream):
    """carry = (decayed count of experiment words so far in this document, document id)."""
    count, doc = carry if carry is not None else (0.0, None)
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if prefix.document_ids[-1] != doc:
        count = 0.0
    context = min(count, MAX_CONTEXT)
    if token in FIGURE_REFS:
        value = 0.50 + 0.09 * context
    elif token in HIGH:
        value = 0.52 + 0.37 * context
    elif token in MID:
        value = 0.31 + 0.23 * context
    elif token in LOW:
        value = 0.14 + 0.10 * context
    elif token in CLOSING_BRACE:
        value = 0.46
    else:
        value = 0.0
    if token.strip() in ("control", "controls") and previous in SOFTWARE_CONTROL_BEFORE:
        value = 0.0
    count = DECAY * count + (1.0 if token in WORDS else 0.0)
    return (count, prefix.document_ids[-1]), float(value)

programs.sol:
"""A lexical fall/drop signal, rather than a test of physical motion.

Fall and drop inflections fire strongly, settling/collapse and autumn less.
Chinese descending/falling roots fire too, especially standalone 落. Common
compound spellings alter its gain; this also covers Japanese 落ち. Immediately
following prepositions/direction words get an echo. Case and token boundaries
matter. All other tokens get zero; incomplete bytes and background are omitted.
"""
READS = ()
FALL = {'fall', 'falls', 'falling', 'fallen', 'fell'}
DROP = {'drop', 'drops', 'dropping', 'dropped'}
SETTLE = {'settle', 'settles', 'settled', 'settling'}
COLLAPSE = {'collapse', 'collapses', 'collapsed', 'collapsing'}
ROOT_GAINS = {
    '降': 0.90, '沉': 0.58, '秋': 0.58, '掉': 0.72,
    '跌': 1.20, '堕': 1.20, '墮': 1.20, '坠': 1.05,
}
# These preceding characters form common word-internal uses of 落.
COMPOUND_PREFIXES = set('下低散冷击擊座洒缺沒没院')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if word in FALL:
        value = 1.35 if token[:1].isspace() else 0.70
        if token[:1].isspace() and raw[:1].isupper():
            value = {'fall': 1.10, 'falls': 1.24, 'falling': 1.35,
                     'fallen': 0.90, 'fell': 0.56}[word]
    elif word in DROP or word in {'.drop', '_drop', '-drop'}:
        value = 1.15 if token[:1].isspace() else 0.98
        if word in {'dropping', 'drops'}:
            value = 1.00
    elif word in SETTLE:
        value = 0.65
    elif word in COLLAPSE or word in {'lounge', 'autumn'}:
        value = 0.55
    elif word == 'fallback':
        value = 0.70

    if token == '落':
        value = 6.40
        if previous.endswith('段'):  # 段落 means paragraph.
            value = 3.80
        elif previous[-1:] in COMPOUND_PREFIXES:
            value = 5.30
    elif token in ROOT_GAINS:
        value = ROOT_GAINS[token]
    elif token == '落地':
        value = 2.30
    elif len(token) == 2 and token[0] == '落' and token[1] in '在到下入':
        value = 2.80
    elif token in {'落ち', '部落'}:
        value = 2.05
    elif token == '落实':
        value = 1.05
    elif token in {'角落', '坐落', '落幕', '落ち着'}:
        value = 0.55
    elif '落' in token:
        value = 1.50 if len(token) == 2 else 0.25
    elif token in {'下降', '投降', '掉了', '下跌', '降临'}:
        value = 0.60

    if previous in FALL:
        if word == 'of':
            value += 0.90
        elif word == 'in':
            value += 0.34
        elif word in {'into', 'on', 'off', 'apart', 'to', 'down', 'out', 'under'}:
            value += 0.22
        elif word in {'at', 'within', 'back', 'from', 'below'}:
            value += 0.10
    elif previous in DROP and word == 'of':
        value += 0.50
    return (doc, word), float(value)

programs.luna:
"""Flag words about falling, dropping, lowering, or settling downward."""

READS = ()

FALLING_WORDS = {
    "fall", "falls", "fell", "fallen", "falling",
    "drop", "drops", "dropped", "dropping",
    "settle", "settles", "settled", "settling",
    "collapse", "collapses", "collapsed", "collapsing",
}

DOWN_WORDS = {"落地", "落实", "降", "降温", "沉", "掉"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,;:!?()[]{}\"'")
    if word in FALLING_WORDS or word in DOWN_WORDS:
        return carry, 1.0
    return carry, 0.0

programs.sol:
"""A detector for text boundaries, symbolic marks, and invitations with 'let'.

Most prose has a near-zero response. Document endings, non-ASCII symbols,
programming arrows/bars, and 'let me', 'let us', or 'let’s' receive positive
responses.
Hyphens are strongest inside words, weak after digits, and negative when
starting a line. Unicode minus and hyphen characters have much stronger
responses than the ordinary ASCII hyphen. The numbers are rounded typical
training responses. Chat boundaries have small negative responses; unusual
spacing/control characters and the interjection "Wait" have separate rules.
For a split UTF-8 character, use its completed character when available;
otherwise leave a small uncertain response rather than guess its identity.
"""
import unicodedata as unicode

READS = ()


def symbol_value(mark, spaced):
    if not mark:
        return 0.0
    if mark == '−':
        return 1.85 if spaced else 2.19
    if mark == '‐':
        return 2.45
    if mark == '–':
        return 0.50 if spaced else 0.97
    if mark in ('—', '——'):
        return 0.14 if spaced else 0.30
    if '->' in mark and '--' not in mark and not any(c.isalpha() for c in mark):
        return 0.81 if spaced else 0.91
    if mark in ('<<', '||'):
        return 0.80
    if mark == '&&':
        return 0.66
    if mark == '>>':
        return 0.18
    if mark == '|':
        return 0.63
    if mark == ')|':
        return 0.60
    if mark and all(c == '¯' for c in mark):
        return min(2.5, 1.3 + 0.3 * len(mark))
    if mark and all(c == '·' for c in mark):
        return 0.40
    if len(mark) != 1:
        return 0.0
    if mark in '′″':
        return 1.65
    if mark in '†‡':
        return 1.25
    if mark in '¿¡':
        return 0.95
    if mark in '×÷≤':
        return 0.27
    if mark == '∣':
        return 1.65
    if mark in '⟨⟩':
        return 1.20
    if mark in '✓✔✅':
        return 1.30 if spaced else 1.15
    if mark == '°':
        return 0.20
    if mark == '„':
        return 0.41
    if mark in '§・':
        return 0.43
    if mark in '¶‰※':
        return 0.78
    category = unicode.category(mark)
    if category == 'Sm' and ord(mark) > 127:  # Mathematical symbols.
        return 0.60
    if category == 'So':  # Decorative and other symbols.
        return 0.85
    if category == 'Sk' and ord(mark) > 127:  # Standalone accent marks.
        return 0.90
    if category == 'Cf':  # Invisible formatting marks.
        return 1.0
    if category == 'Co':  # Private-use font glyphs.
        return 0.65
    if category == 'Zs' and mark != '\xa0':  # Unusual space characters.
        return 0.95
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    mark = token.strip(' \t\n\r')
    value = symbol_value(mark, token.startswith(' '))
    if token == '<|endoftext|>':
        value = 1.38
    elif token == '<|im_end|>':
        value = -0.11
    elif token == '<|im_start|>':
        value = -0.076
    elif (previous.strip().lower() == 'let'
          and token in (' me', ' us', "'s", '’s')):
        if token in (' me', ' us'):
            value = 0.94 if token == ' me' else 0.85
        elif token in ("'s", '’s'):
            value = 1.07
    elif mark == '-':
        if not previous or previous.endswith('\n'):
            value = -0.10 if token == '-' else 0.0
        elif previous[-1:].isalpha():
            value = 0.43 if token == '-' else 0.09
        elif previous.strip().isdigit():
            value = 0.03 if token == '-' else -0.055
        else:
            value = 0.18 if token == '-' else 0.0
    elif token == '\r':
        value = 0.78
    elif token == '\x00':
        value = 0.33
    elif '\xa0' in token:
        value = -0.06 if token == '\xa0' else 0.44
    elif mark == '|':
        value = 0.50 if previous.strip().isdigit() else 0.65
        if '\n' in token:
            value = 0.18
    elif token == '\ufe0f':
        value = 1.60
    elif token == 'Wait':
        value = 0.25
    elif '�' in token:
        # Only the last glyph is needed, and only for rare byte-fragment tokens.
        char = prefix.text_prefixes[-1][-1:]
        value = 0.15 if char == '�' else symbol_value(char, False)
        if char and unicode.category(char) == 'Cc':
            value = 0.95
    return (doc, token), float(value)

programs.haiku:
"""Symbol detector: fires on the end-of-text token, on minus/dash signs and other
operator-like symbols (pipes, arrows, check marks, math signs), and on the object
pronoun right after "let" (let me / let's / let us)."""

READS = ()

EOT = "<|endoftext|>"
MINUS_SIGNS = set("−‐‑‒⁻¯′″∣")  # minus, hyphens, macron, primes, divides
CHECKS = set("✓✗✅❌")
STARS_MARKS = set("☆★✭✝†○")
ARROWS = set("→⇒➡")
MATH = set("√≈≠±∫≡≫⟨⟩")
PIPES = {"|", "||", "&&", "<<", "->", "|\\", "()->", "')->"}
DOTS = set("·・")
REPLACEMENT = "�"


def level(s):
    """Activation for a token that is not 'let' + pronoun."""
    if s == EOT:
        return 1.4
    b = s.strip(" ")
    if not b:
        return 0.0
    if any(ch in MINUS_SIGNS for ch in b):
        return 2.0
    if b == "–":
        return 0.8
    if b.strip() in PIPES:
        return 0.7
    if any(ch in CHECKS or ch in STARS_MARKS for ch in b):
        return 1.2
    if any(ch in ARROWS or ch in MATH for ch in b):
        return 0.7
    if any(ch in DOTS for ch in b):
        return 0.4
    if b == "-":
        return 0.2
    if b == "\r":
        return 0.7
    if REPLACEMENT in b:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if prev == "let" and s.strip() in ("me", "'s", "’s", "us"):
        return carry, 1.0
    return carry, level(s)

programs.sol:
"""Estimate an unfinished backslash escape or Unicode-character introducer.

The largest response is to a token consisting of space + backslash. A bare
backslash is next; punctuation-attached backslashes are weaker. Plain
backslashes respond more early in a document and after real newlines, less
after another escape. Completed escapes get a small negative estimate.
A few space-prefixed, incomplete UTF-8 character classes also respond.
Other tokens are left at zero: this omits small, word-specific responses.
"""
READS = ()
BACKSLASH = '\\'

# IDs are needed because these distinct byte fragments decode alone as " �".
MATH_OPERATOR_START = {11995}       # space + E2 88: U+2200..U+223F
GREEK_START = {7851}                # space + CE: U+0380..U+03BF
LATIN1_START = {1683}       # space + C3: U+00C0..U+00FF
SYMBOL_BLOCK_START = {2858}         # space + E2: U+2000..U+2FFF
HIGH_BMP_START = {32495}            # space + EF: U+F000..U+FFFF
INDIC_BLOCK_STARTS = {
    27982, 14925, 35178, 69033, 70597, 93255,
}  # space + E0, sometimes followed by an Indic-block byte


def unfinished_unicode(token):
    if token in MATH_OPERATOR_START:
        return 0.82
    if token in GREEK_START:
        return 0.47
    if token in LATIN1_START or token in SYMBOL_BLOCK_START:
        return 0.54
    if token in HIGH_BMP_START:
        return 0.69
    if token in INDIC_BLOCK_STARTS:
        return 0.48
    return 0.07


def attached_backslash(head):
    if head.endswith("{"):
        return 0.26
    if head.endswith(("(", "[")):
        return 0.40
    if head.endswith("$"):
        return 0.14
    if head.endswith(("_", "|")):
        return 0.25
    if head == "*":
        return 0.0
    if head.endswith("^"):
        return 0.39
    if BACKSLASH in head:
        return 0.32
    if head.endswith((".", ",")):
        return 0.65
    if head.endswith(":"):
        return 0.48
    return 0.55


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, previous, before_previous = 0, "", ""
    else:
        _, position, previous, before_previous = carry

    if text in (BACKSLASH, " " + BACKSLASH):
        spaced = text.startswith(" ")
        if position == 0:
            value = 0.53 if spaced else 0.058
        else:
            value = 1.18 if spaced else 0.79
            value += (1.20 if spaced else 0.78) / (position + 1) ** 0.5
            if "\n" in previous:
                value += 0.44 if spaced else 0.54
            elif previous.isspace():
                value += -0.15 if spaced else 0.39
            if BACKSLASH in previous:
                value -= 0.68 if spaced else 0.38
            if previous in ("n", "t", "r") and BACKSLASH in before_previous:
                value -= 0.37 if spaced else 0.44
            if not spaced:
                if previous[-1:].isdigit():
                    value += 0.22
                if "$" in previous:
                    value += 0.14
            value = max(0.0, value)
    elif text.endswith(BACKSLASH) and not text.endswith(BACKSLASH * 2):
        value = attached_backslash(text[:-1])
    elif text.startswith(BACKSLASH):
        value = -0.075
    elif text == " \ufffd":
        value = unfinished_unicode(int(prefix.token_ids[-1]))
    else:
        value = 0.0

    return (document, position + 1, text, previous), value

programs.luna:
"""Predict small responses to backslash punctuation and one broken-byte token."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\\" in token:
        return None, 0.34
    if token == " \ufffd":
        return None, 0.20
