programs.sol:
"""A negative document-opening pulse, especially on bare Latin letters.

Opening words without a leading space get a smaller pulse. Common opening
articles, questions and source-code headers are stronger than other words.
The pulse has a weak, rapidly fading tail over the next few tokens.
NUL bytes after lowercase ASCII letters get a strong negative response,
as in misdecoded UTF-16 text. Message/tool boundaries get small offsets.
"""
import unicodedata

READS = ()
QUESTION_WORDS = {'what', 'why', 'how', 'when', 'where', 'who', 'which'}
MODULE_HEADERS = {'import', 'package', 'from', 'export'}


def opening(s):
    word = s.strip()
    spaced = bool(s and s[0].isspace())
    n = len(word)
    if not word:
        if '\n' in s or '\r' in s:
            return -0.28 if len(s) == 1 else 0.0
        return -0.60 if ' ' in s else -0.40
    if word.startswith('<|'):
        return 0.0
    if word.isascii() and word.isalpha():
        lower = word.lower()
        if n == 1:
            if spaced:
                return -0.85 if word == 'A' else -1.30
            if word == 'A':  # Also the indefinite article.
                return -3.0
            if lower in 'qyz':  # Rare Latin initials are weaker.
                return -2.4 if word.isupper() else -2.6
            if word.isupper():
                return -3.5 if word in 'OU' else -4.2
            return -2.9 if word in 'eiou' else -3.6
        if lower == 'the' and not word.isupper():
            return (-1.24 if word[0].isupper() else -0.34) if spaced else -1.65
        if lower == 'this' and not word.isupper():
            return (-0.8 if word[0].isupper() else -0.12) if spaced else -1.3
        if lower in QUESTION_WORDS and not word.isupper():
            return (-0.65 if word[0].isupper() else -0.20) if spaced else -1.15
        if word in MODULE_HEADERS and not spaced:
            return -1.60
        if spaced:
            return -0.20 if word.islower() else -0.40
        if word.isupper():
            return -0.43
        if word.islower():
            return -0.75
        return -1.0 if n <= 3 else -0.60
    if word.isdigit():
        return -0.15 if word == '0' else -0.67
    if '\ufffd' in word:
        return -0.75
    if s.startswith('\\'):
        return -1.5
    if s.startswith(('#', '//', '/*', '<?')):
        return -1.2
    if all(not c.isalnum() for c in word):
        if set(word) <= set('.,:;!?，。！？：；'):
            return 0.10
        return -0.40
    if n == 1 and 'CYRILLIC' in unicodedata.name(word, ''):
        return -1.8 if word.isupper() and not spaced else -0.65
    return -0.20


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position = 0
    else:
        position = carry[1] + 1
    if position == 0:
        value = opening(prefix.token_strings[-1])
    else:
        s = prefix.token_strings[-1]
        value = -0.07 * 0.6 ** (position - 1) if position < 12 else 0.0
        if '\x00' in s:
            previous = prefix.token_strings[-2]
            if previous.isascii() and previous.isalpha() and previous.islower():
                value -= 1.28 + 2.3 * 0.88 ** position
            else:
                value -= 0.22
        elif s == '<|im_end|>' or s in {'<tool_call>', '</tool_call>'}:
            value -= 0.11
        elif s == '<|endoftext|>':
            value -= 0.025
        elif s == '</think>':
            value += 0.10
    return (document, position), float(value)

programs.luna:
"""Predict a sparse document-opening pulse, with a stronger one-letter signal."""
READS = ()

def step(carry, prefix, upstream):
    t = prefix.position
    first = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return None, 0.0

    token = prefix.token_strings[-1]
    if token.isascii() and token.isalpha():
        if len(token) == 1:
            value = -3.6
        elif token.isupper():
            value = -0.3
        elif token.istitle():
            value = -0.8
        else:
            value = -0.62
    elif token and token[0].isspace():
        value = -0.22
    elif token.isdigit():
        value = -0.56
    else:
        value = -0.05
    return None, value

programs.haiku:
"""Italy detector for layers.0.mlp.down_proj:5448.

The component is mostly silent (near 0 on almost every token). Its clearest behaviour
is negative, and it is a lexical response to Italian-language words, read off the newest
token alone:
  * "Italian", "Italy", "Italia" and related forms: strongest (about -1.4);
  * Italian given names and Italian city or region names: about -1.0;
  * common Italian words that are not shared with English: più, sempre, anche, questo,
    molto, stato, sia, mondo, giorno, ... : about -0.6;
  * word-pieces with Italian-only endings (-zione, -ità, -enza, -izz-, -azz-) and
    Italian accented word endings (à, è, ì, ò, ù): about -0.5.
Everything else is predicted as 0. The program keeps no state between tokens.
"""
import re

READS = ()

ITALY = {"Italian", "Italy", "Italia", "Italiano", "Italiana", "Italiani", "Italians",
         "italian", "italiano", "italiana", "italiani"}
PLACES = {"Milano", "Milan", "Naples", "Napoli", "Roma", "Florence", "Venice", "Sicily",
          "Sicilia", "Torino", "Bologna", "Palermo"}
NAMES = {"Giovanni", "Giov", "Francesco", "useppe", "Luigi", "Mario", "Paolo", "Giorgio",
         "Pietro", "Carlo", "Antonio", "Marco", "Michele", "Roberto", "Franco", "Giuseppe",
         "Gian", "Alberto", "Leonardo", "Sergio", "Luca", "Lorenzo", "Andrea", "Aless", "Lucia"}
WORDS = {"più", "anche", "sempre", "questo", "questa", "molto", "tutto", "suo", "sua",
         "loro", "stato", "stata", "sia", "essere", "perché", "perchè", "però", "così", "già",
         "mondo", "pasta", "nostro", "nostra", "mio", "mia", "bene", "sarà", "oggi", "stesso",
         "stessa", "qualche", "giorno", "giorni", "anno", "anni", "vita", "storia", "valore",
         "cosa", "ciò", "oltre", "dopo", "quello", "quella", "proprio", "ragazzo"}
ITALIAN_ENDING = re.compile(r"(zion|ità|enza|izz|azz)")
WORD = re.compile(r"[a-zà-ú]{4,}")
ACCENT_END = re.compile(r"[àèìòù]$")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    w = raw.strip()
    if w in ITALY:
        return None, -1.4
    if w in PLACES or w in NAMES:
        return None, -1.0
    if w in WORDS:
        return None, -0.6
    if WORD.fullmatch(w) and ITALIAN_ENDING.search(w):
        return None, -0.5
    if not raw.startswith(" ") and ACCENT_END.search(w):
        return None, -0.5
    return None, 0.0

programs.luna:
"""A lexical proxy for common prepositions, with a few local-context adjustments."""
from collections.abc import Mapping

READS = ()

