"""layers.0.mlp.down_proj:5456 -- "indented code line opener" detector.

This component writes a negative value into the residual stream on the first token of an
indented line of code, and stays near zero on prose and on unindented text. The push is
strongest for control-flow and declaration keywords (if, for, return, const, def, else...),
for closing braces and comment markers (}, //, ///, #, */), and it grows with the depth of
indentation (more tabs or spaces before the token). Bare tab tokens and comment/annotation
markers (@, //, #) elsewhere get a weaker negative push.

Plain-language rule:
  1. Is the token the first thing on an indented line (a whitespace-only token with a tab or
     two or more spaces just before it, or a token that itself starts with a tab)?
  2. If so: -0.8 for a keyword, -0.7 for a closer or comment marker, -0.35 for anything else,
     multiplied by (1 + 0.1 * indentation depth).
  3. Otherwise: a bare tab token -0.25, a comment or annotation marker -0.15, else 0.
"""
READS = ()

KEYWORDS = set(
    "if elif else for while return def const let var func case switch break continue "
    "throw try catch import assert print go".split()
)
CLOSERS = {"}", "{", "//", "///", "#", "*", "*/", "/**", "]", ")", "});", "}\n", "}\n\n"}
MARKERS = {"@", "//", "/**", "#"}


def _is_indent(s):
    # whitespace only (no newline) containing a tab, or at least two spaces
    return s != "" and s.strip() == "" and "\n" not in s and ("\t" in s or len(s) >= 2)


def _depth(strs):
    # indentation of the current line up to this token: tabs count 1, four spaces count 1
    text = ""
    for s in reversed(strs):
        if "\n" in s:
            text = s.split("\n")[-1] + text
            break
        text = s + text
    lead = text[: len(text) - len(text.lstrip())]
    return lead.count("\t") + lead.count(" ") / 4


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    cur = strs[-1]
    same_doc = len(strs) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = strs[-2] if same_doc else ""
    core = cur.strip()
    if core and (_is_indent(prev) or cur.startswith("\t")):
        if core in KEYWORDS:
            base = -0.8
        elif core in CLOSERS or core.startswith("//"):
            base = -0.7
        else:
            base = -0.35
        return None, base * (1 + 0.1 * min(_depth(strs), 5))
    if cur == "\t":
        return None, -0.25
    if core in MARKERS:
        return None, -0.15
    return None, 0.0

