import re

READS = ()
RESULT_VERBS = {'obtain', 'receive', 'achieve', 'yield', 'derive',
                'acquire', 'score', 'deserve', 'attain', 'earn'}
GETTER = re.compile(r'^[._/(:#=-]?[gG]et(?:$|[A-Z_])')
