LEXICAL_DE = {'得意', '得罪', '得益', '得住', '懒得', '舍不得',
              '不得不', '得益于', '所得税', '彼得'}
# Characters for reach, enter, return, arise, lose, and acquire.
ACTION_CHARACTERS = {'到': 0.33, '入': 0.45, '回': 0.30, '起': 0.34,
                     '失': 0.46, '获': 0.70, '獲': 0.70}
COMPLEMENT_DE = {'不得', '还得', '只得', '就得',
                 '做得', '看得', '说得', '打得'}


def result_verb(word):
    for ending in ('', 's', 'ed', 'ing', 'd'):
        if not ending or word.endswith(ending):
            base = word[:-len(ending)] if ending else word
            if base in RESULT_VERBS or base + 'e' in RESULT_VERBS:
                return True
    return False


