    lower = word.lower()
    if word == '得':
        return 5.05
    if word in {'德', '徳'}:
        return 1.85
    if '得' in word:
        if word in LEXICAL_DE:
            return 1.2
        if any(part in word for part in COGNITION):
            return 1.3
        if word.startswith(('获得', '獲得', '使得', 'お得')):
            return 1.4
        if word.startswith(('得到', '取得', '赢得', '贏得', 'を得')):
            return 2.4
        if word in COMPLEMENT_DE:
            return 3.8
        return 3.0 if len(word) == 2 else 1.4
    if lower in {'get', 'gets', 'getting'}:
        return 0.84 if lower == 'getting' else 0.73
    if lower in {'got', 'gotten'}:
        return 0.90
    if lower in {'return', 'returns', 'returned', 'returning'}:
        return 0.88 if lower == 'return' else 0.65
    if lower == 'into':
        return 0.62
    if lower in {'obtained', 'deemed'}:
        return 1.15
    if word.startswith(('.getElementBy', '.getElementsBy')):
        return 0.20
    if word == '.get':
        return 0.59
    if GETTER.match(word) or lower in {'getattr', 'getch', 'getcwd', 'gettext'}:
        return 0.85
    if result_verb(lower.lstrip('._-')):
        return 0.58
    if lower in {'give', 'gives', 'giving'}:
        return 0.20
    if lower.startswith(('получ', 'олуч', 'obten', 'bekom')):
        return 1.05
    if lower in {'được', 'får', 'ได', 'ได้'}:
        return 0.85
    if word == '득':
        return 2.2
    if word == 'dé':
        return 1.05
    return max((value for char, value in ACTION_CHARACTERS.items()
