"""Layer-0 MLP down-projection component 5462: a "variable algebra" dip and a "list bullet" spike.

Plain-language reading. The component is most negative when a bare one-letter variable
is followed by an operator or a sub/superscript (x=, a+, b-, x^, p₁, t²): the value is
about -0.8 for operators and about -0.3 for a digit written right after the letter. It
is strongly positive on a dash that opens a line as a bullet ("\n- item"), about +1.3.
It is mildly positive on a spaced dash in prose (" – ", " -"), about +0.3. Superscript and
subscript characters elsewhere are slightly negative. Everything else is 0.

The program needs only the previous token and the current token, so it is a
two-token rule set. Values are the group means measured on training rows.
"""

READS = ()

SCRIPT = set("₀₁₂₃₄₅₆₇₈₉⁰¹²³⁴⁵⁶⁷⁸⁹")
OPERATORS = {"=", "+", "-", "^", "_", "_{", "^{", "}_{", "–", "*", "**", "(", "\\"}
DASHES = {"-", "–"}


def is_variable(token):
    """A bare one-letter variable, possibly with a leading space or bracket: ' x', '(a', 'y'."""
    core = token.lstrip(" ([{")
    return len(core) == 1 and core.isalpha()


def is_script(token):
    return len(token) > 0 and all(c in SCRIPT for c in token)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    stripped = token.strip()
    if stripped in DASHES and (prev.endswith("\n") or prev.strip() == ""):
        return None, 1.3  # a dash opening a line: a list bullet
    if is_variable(prev):
        if stripped in OPERATORS or is_script(token):
            return None, -0.8  # operator or script right after a bare variable
        if stripped.isdigit():
            return None, -0.3  # digit right after a variable, as in p1 or t2
        return None, 0.0
    if token in (" -", " –"):
        return None, 0.3  # spaced dash in prose
    if is_script(token):
        return None, -0.2  # sub/superscript not after a variable
    return None, 0.0

programs.luna:
"""Approximate a text-level syntax cue: equation and exponent marks tend
negative, while a dash opening a fresh line tends strongly positive. A short
history separates that dash from a minus sign; the predictions are shrunk to
80% of these rule values.
"""
import unicodedata

READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    before = history.rstrip()
    last = before[-1:] if before else ""
    if word in ("=", "=="):
        if token[:1].isspace():
            value = -0.27
        elif last.isdigit():
            value = -0.15
        else:
            value = -0.55
    elif word == "+":
        value = -0.30
    elif word == "^":
        value = -0.65
    elif word == "_":
        value = -0.18
    elif word == "'":
        value = -0.30
    elif word == "\\":
        line = history.rsplit("\n", 1)[-1]
        if any(c in line for c in "$_^{}"):
            value = -0.30
    elif word == "−":
        value = -0.70
    elif any(unicodedata.category(c) == "No" for c in word):
        value = -0.85
    elif word.isdecimal():
        value = -0.025
    elif word == "(":
        value = -0.20 if last.isalpha() else -0.05
    elif word == "[":
        value = -0.10
    elif word in ("-", "–", "—"):
        line = history.rsplit("\n", 1)[-1]
        if not line.strip():
            value = 1.45
        elif before.endswith((".", "!", "?", ":", ";")):
            value = 0.45
        elif any(c in line[-20:] for c in "=+^*/()[]"):
            value = -0.35
        else:
            value = 0.20
    elif any(unicodedata.category(c) == "Sm" for c in word):
        value = -0.13
    elif "�" in word:
        value = -0.15

    return (doc, (history + token)[-96:]), float(value * 0.8)

programs.haiku:
"""Machine detector: fires on words for machines, engines, mechanisms and devices, in English and in
Chinese (机 / 機 = machine), more weakly on random/chance words and on system, method and agent nouns."""
READS = ()

TIERS = (
    (2.5, {"machine", "machines", "machinery", "machining", "engine", "engines", "engine", "引擎",
           "cơ", "기", "械"}),
    (1.5, {"mechanism", "mechanisms", "mechanical", "mechanics", "opportunity", "opportunities",
           "random", "randomly", "randomized", "organic", "organism", "organisms", "device", "devices",
           "设备", "motor", "motors", "aircraft", "airplane", "apparatus", "equipment"}),
    (0.8, {"system", "systems", "computer", "computers", "mac", "vm", "technique", "techniques",
           "technology", "method", "methods", "window", "windows", "platform", "platforms", "平台",
           "camera", "instance", "instances", "agent", "agents", "agency", "agencies", "host", "plane",
           "mode", "appliance", "drone", "器", "台", "系统", "电脑"}),
)
SCORE = {w: value for value, words in TIERS for w in words}

def word_score(token):
    w = token.strip().lower()
    if w in ("机", "機"):
        return 8.0           # the single character for "machine"
    if "机" in w or "機" in w:
        return 3.0           # compounds: 机器 machine, 机会 chance, 手机 phone, ...
    if "machin" in w and w not in SCORE:
        return 2.5
    return float(SCORE.get(w, 0.0))

def step(carry, prefix, upstream):
    return None, word_score(prefix.token_strings[-1])

programs.sol:
"""Detect a transition into a two- or three-letter uppercase Latin chunk.

Two capitals are strongest; continuing an uppercase run is suppressed. Spelling
also matters: certain initial/final I/O/U vowels, X, repeated letters, and
Roman-numeral-like spellings
give weaker signals. A few common words and reference labels are attenuated.
Digits or a separator after capitals soften the transition. Other tokens and
document starts predict zero; the two-token context resets at document changes.
"""
import re

READS = ()
WORDS = set('AND ARE BUT CAN DID FOR GET HAS HAD HOW NOT NOW ONE OUR OUT '
            'PUT RUN SAY SEE SET SHE THE TOO TWO USE WAS WAY WHO WHY YOU'.split())
LABELS = {'ID', 'FIG', 'URL'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    beginning = carry is None or carry[0] != document
    previous, before = ('', '') if beginning else carry[1:]
    previous_word = previous.strip()
    value = 0.0
    if (not beginning and word.isascii() and word.isalpha()
            and word.isupper() and len(word) in (2, 3)
            and not previous_word[-1:].isupper()):
        if len(word) == 2:
            value = -1.90 if token.startswith(' ') else -1.75
            if word[0] in 'IU':
                value += 0.35
            elif word[0] == 'O':
                value += 0.20
            if word[-1] in 'IOU':
                value += 0.45
        else:
            vowels = sum(c in 'AEIOU' for c in word)
            value = -0.85 + 0.15 * vowels
        if 'X' in word:
            value += 0.55
        if len(set(word)) == 1:
            value += 0.30
        if re.fullmatch('[IVX]+', word):
            value += 0.50 if len(word) == 2 else 0.20
        if word in WORDS:
            value += 0.40
        if word in LABELS:
            value += 0.95 if word == 'ID' else 0.65
        if previous_word[-1:].isdigit():
            value *= 0.70
        elif before.strip()[-1:].isupper():
            value *= 0.65
        elif previous.isspace() and '\n' not in previous:
            value *= 0.80
        value = min(value, 0.0)
    return (document, token, previous), value

programs.luna:
"""A short capital-letter token often marks a new acronym."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if not (word.isascii() and word.isalpha() and word.isupper()):
        return None, 0.0

    length = len(word)
    if length not in (2, 3):
        return None, 0.0

    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
        if previous and previous[-1].isupper():
            return None, 0.0

    starts_word = token[:1].isspace()
    if length == 2:
        return None, -1.7 if starts_word else -1.4
    return None, -0.68 if starts_word else -0.65

programs.sol:
"""Strong lexical spikes, not a general semantic classifier.

FOR, MESSAGE/MSG and LESSON are positive; DURING/DOING and Chinese activity
verbs are negative. Lowercase ' for' is weaker in common governed phrases
(ready for, need for, look for) than in mathematical or independent clauses.
A few other spatial/temporal words have small negative responses. Everything
else is zero, leaving the component's weaker word-specific effects unexplained.
"""
READS = ()

PREPARATION = set('prepare preparing prepared ready ask asks asked asking'.split())
FOR_COMPLEMENTS = set(
    'need needs demand responsible grateful allow allows designed '
    'look looking search searches account accounts accounting accounted '
    'suitable suited eligible liable apply applying support'.split()
)
PURPOSE_WORDS = set(
    'reason reasons plan plans recipe tool tools crucial essential needed available '
    'provides pay petition useful important necessary required recommended perfect '
    'room waiting play plays played materials funds tips strategies '
    'opportunity opportunities help preparation love care call'.split()
)
USE_WORDS = set('used provided worked made employed use work works easy easier beneficial'.split())
MATH = set('equation equations expression formula solve solving values coordinates '
           'digits positive same standard similarly then true stands constant'.split())
CONNECTIVES = set('and but so that is are was be as than'.split())


def prose_for(previous):
    p = previous.strip().lower()
    if p in PREPARATION:
        return -0.27
    if p in FOR_COMPLEMENTS:
        return -0.10
    if p in PURPOSE_WORDS:
        return 0.08
    if p in USE_WORDS:
        return 0.23
    if p in MATH or not p:
        return 0.75
    if p in CONNECTIVES or not any(c.isalpha() for c in p):
        return 0.61
    if p in {'you', 'it', 'them', 'us', 'him', 'her'}:
        return 0.24
    if p.endswith('ing'):
        return 0.30
    return 0.44


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = s.strip().strip('._-()[]{}:,;\"\'`“”').lower()
    value = 0.0
    if word == 'for':
        if s == ' for':
            same_doc = (len(prefix.document_ids) > 1 and
                        prefix.document_ids[-2] == prefix.document_ids[-1])
            value = prose_for(prefix.token_strings[-2]) if same_doc else 0.85
        else:
            value = 0.81
            if '\t' in s:
                value = 0.97
            elif s == ' FOR':
                value = 0.44
            elif s.startswith(' '):
                value = 0.70
    elif word in {'during', 'doing'}:
        value = -1.53 if s.startswith(' ') else -1.60
    elif word in {'lesson', 'lessons'}:
        value = 1.62 if word == 'lesson' else 1.46
    elif word in {'message', 'messages', 'msg'} or s.endswith('Message'):
        value = 0.72
        if word == 'messages':
            value = 0.44
        elif word == 'msg':
            value = 0.63
        elif s.startswith('.') or (s.endswith('Message') and word != 'message'):
            value = 1.0
    elif s in {'消息', '的消息'}:
        value = 0.54
    elif s in {'参加', '开展', '开展了', '举办'}:
        value = {'参加': -1.46, '开展': -1.23, '开展了': -1.1, '举办': -0.81}[s]
    elif s in {' do', ' going'}:
        value = -0.20
    elif s in {' throughout', ' along', ' against', ' behind'}:
        value = -0.24
    elif s in {' under', ' over', ' before', ' between', ' within', ' through', ' when'}:
        value = -0.08
    return None, float(value)

"""Recognize 照, its compounds, and its photographic/lighting/accordance senses.

照 alone is the strongest cue. In the split word 按 + 照 ('according to'),
its response is smaller. Compounds and translations have weaker responses.
The Korean syllable 조 and the photographic fragment 'oto' also trigger this
lexical approximation, even when their surrounding word has another meaning.
A colon after document-initial Title and two phrase completions are also
modeled. Other tokens receive zero; weak background responses are omitted.
"""

READS = ()

# Common compounds of 照, calibrated separately because they differ greatly.
COMPOUNDS = {
    '按照': 2.16,     # according to
    '对照': 4.2,      # compare against
    '参照': 2.75,     # refer to
    '依照': 2.72,     # in accordance with
    '照明': 1.84,     # illumination
    '照顾': 1.16,     # take care of
    '照射': 1.99,     # irradiation
    '日照': 2.6,      # sunshine
    '光照': 2.65,     # illumination
    '照亮': 1.3,      # light up
    '照料': 1.55,     # take care of
    '照顧': 1.12,     # traditional spelling
    '照样': 1.06,     # as before
}

# Complete split compounds: according to, follow, imitate, snapshot, license.
SPLIT_COMPOUNDS = {'按': 3.1, '遵': 3.6, '仿': 3.5, '快': 3.9, '执': 4.4}

ACCORDING_TO = {'依據', '依据', '依法', '按规定', '制定'}
LIGHT_WORDS = {'candle', 'candles', 'irradi', 'lighting', 'illumination'}
COMPARISON_WORDS = {'match', 'matches', 'comparison', 'compared', 'contrast'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    same = carry is not None and carry[0] == document
    previous = carry[1] if same else ''
    position = carry[2] + 1 if same else 0
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower().lstrip('/-(.')
    value = 0.0

    if token == '照':
        # Read the decoded suffix here to recover preceding split UTF-8 bytes.
        char = prefix.text_prefixes[-2][-1:] if same else ''
        value = SPLIT_COMPOUNDS.get(char, 6.35)
    elif token in COMPOUNDS:
        value = COMPOUNDS[token]
    elif token.endswith('按照'):
        value = 2.2
    elif '照片' in token or token == '拍照':
        value = 0.78
    elif token in {'按', '依'}:
        value = 0.79
    elif token in ACCORDING_TO:
        value = 0.54
    elif token == '根据':
        value = 0.28
    elif token == '조':
        char = prefix.text_prefixes[-2][-1:] if same else ''
        value = 0.51 if char == '강' else 1.25
    elif token in {'造', '昭', '罩'}:  # related CJK readings/spellings
        value = 0.53
    elif word in {'photo', 'photos', 'photoc'}:
        value = 0.72
        if token[:1] in '/-':
            value = 0.98
        elif token[:1].isupper() and not raw.startswith(' '):
            value = 0.52
    elif word in {'photograph', 'photographs'}:
        value = 0.58
    elif word.startswith('photograph'):
        value = 0.2 if 'er' in word else 0.37
    elif word.startswith('photon'):
        value = 0.36
    elif word == 'phot':
        value = 0.3
    elif word == 'oto':
        value = 0.48
    elif word == 'фото':
        value = 0.59
    elif word.startswith('фотограф'):
        value = 0.33
    elif word == 'accordance':
        value = 0.65
    elif word in {'according', 'accordingly'}:
        value = 0.16
    elif word == 'соответствии':
        value = 0.85
    elif word == 'chiếu':
        value = 1.54
    elif word in LIGHT_WORDS:
        value = 0.54 if word.startswith('candle') else 0.35
    elif word in COMPARISON_WORDS:
        value = 0.24 if word == 'matches' else 0.15

    if token == '着' and previous == '照':
        value = 2.0
    elif word == 'with' and previous.lower() == 'accordance':
        value = 0.095
    elif token == ':' and previous == 'Title' and position == 1:
        value = 0.362
    return (document, token, position), value

"""A lexical approximation: 'if', imports, declarations, and forum labels.

'If' responds in prose as well as code; 'even/as/only if' are weaker.
Declaration families respond more at line starts or after modifiers,
and less inside longer words. Forum labels use nearby layout cues.
Everything else predicts zero. Keep only 160 recent characters and
reset that state at each document boundary; this is not a full parser.
"""
import re

READS = ()

# (Inline, line-start, after-modifier) strengths, shared by word families.
FAMILIES = (
    ('public private protected', (0.05, 1.45, 1.45)),
    ('int void bool boolean', (0.40, 1.25, 2.00)),
    ('double float uint', (0.15, 1.00, 1.45)),
    ('String char long', (0.05, 0.60, 1.20)),
    ('string', (0.00, 0.20, 1.25)),
    ('struct', (0.50, 1.20, 1.50)),
    ('static final extern inline abstract readonly', (0.10, 0.85, 1.60)),
    ('const var def', (0.45, 1.05, 1.80)),
    ('class function func interface', (0.05, 1.05, 1.80)),
    ('let case pub namespace package async', (0.10, 0.75, 1.10)),
    ('fn', (1.10, 1.15, 1.40)),
)
DECLARATIONS = {w: strengths for words, strengths in FAMILIES
                for w in words.split()}
MODIFIERS = set('''public private protected static final extern export virtual
abstract inline async const readonly override unsafe'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    left = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    # Treat source-listing numbers and escaped newlines as layout.
    line = re.split(r'\n|\\n', left)[-1]
    start = bool(re.fullmatch(r'[ \t\r+\-\d]*(?:\\t)*[ \t]*', line))
    start = start or token.startswith('\t')
    escaped = '\\n' in left[-100:]
    fragment = (not token[:1].isspace() and bool(left)
                and (left[-1].isalnum() or left[-1] == '_'))
    prev = re.search(r'([A-Za-z]+)\s*$', left)
    modified = prev and prev[1] in MODIFIERS
    if word in ('if', 'If', 'IF'):
        if word == 'if':
            value = 1.25 if fragment else 1.06
            if start:
                value = 1.37 if escaped or '\t' in line else 1.47
            if prev and prev[1].lower() in ('even', 'as', 'only'):
                value = 0.55 if prev[1].lower() == 'even' else 0.68
            if prev and prev[1] == 'else':
                value = 1.70
            if token.startswith('\t'):
                value = 1.68
        else:
            value = (1.35 if word == 'IF' else 1.45 if fragment or first
                     else 1.26 if start else 1.20)
    elif re.fullmatch(r'[#.(_;\-]if|_IF|[.\"“—]If', word):
        value = 2.0 if word == '-if' else 1.40
    elif word in ('elif', 'elseif', 'ifdef', 'ifndef'):
        value = 1.35
    elif word.startswith('如果'):
        value = 0.80 if word == '如果' else 0.95
    elif word in ('若', 'Если', 'если', 'Wenn', 'wenn', 'unless'):
        value = 0.48 if word in ('若', 'Wenn') else 0.30
    elif word.lower() in ('import', 'imports', 'importing', 'imported'):
        value = 0.70
        if word == 'import':
            value = 1.10 if token[:1].isspace() else 1.30
            if token.startswith('\t'):
                value = 0.90
            if first:
                value = 2.23
    elif token in ('#define', 'define', 'typedef', ' typedef', '(int'):
        value = 0.40 if token == '(int' else 0.60
    # Forum navigation, reputation counters, and challenge headings.
    elif word == 'permalink':
        value = 3.25 if left.endswith('[#') else 0.75
    elif word == 'Tags' and token[:1].isspace():
        value = 0.10
        if left.rstrip().endswith('Show'):
            value = 2.70 if 'Posts:' in left else 1.78
            if line == 'Show' and 'Posts:' not in left:
                value = 1.20
        if 'permalink' in left:
            value = 1.65
        if left.rstrip().endswith('Hide'):
            value = 0.80 if line == 'Hide' else 1.28
    elif word == 'udos' and left[-1:] in ('K', 'k'):
        value = (2.02 if 'Followers:' in left else 1.27
                 if left.rstrip().endswith('Own K') else 0.85)
    elif token == ' [' and 'Kudos' in left:
        value = 0.45
    elif word == 'views':
        value = 1.35 if '...' in left and re.search(r'\d\s*$', left) else 0.10
    elif word == 'Level' and left.rstrip().endswith('Challenge'):
        value = 1.50
    elif word in DECLARATIONS:
        inline, beginning, modifier = DECLARATIONS[word]
        value = modifier if modified else beginning if start else inline
        if start and escaped:
            value *= 0.80
        if fragment:
            value = 0.10
        if word == 'func' and start:
            value = 1.55 if token == 'func' and not escaped else 0.20
        if word == 'var' and token == 'var' and start and not escaped:
            value = 1.45
        if word == 'package' and first:
            value = 1.00
    return (doc, (left + token)[-160:]), float(value)

programs.haiku:
"""Keyword detector: fires on the code word 'if' and 'import' and on the declaration keywords
of programming languages (void, public, static, int, const, def, ...). Stronger for the
strong ones, weaker for the weak ones, and stronger when the keyword starts a line
(after indentation), as a statement or declaration would. Case-sensitive, as the model is."""
READS = ()

STRONG = {"if", "If", "IF", "elif", "elseif", "import", "void", "static", "public", "fn", "如果"}
MEDIUM = {"private", "protected", "const", "int", "def", "struct", "boolean", "extern", "Import"}
TYPES = {"double", "bool", "float", "var", "String", "char", "class", "func", "pub", "uint"}
WEAK = {"function", "final", "let", "interface", "package", "namespace", "Int"}
LINE_START_BOOST = 1.25


def at_line_start(prefix):
    """True if the newest token opens a line: a tab or newline in it, or only indentation before it."""
    token = prefix.token_strings[-1]
    if token.lstrip(" ")[:1] in ("\t", "\n"):
        return True
    if len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2]
        return before != "" and before.strip() == ""
    return False


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in STRONG:
        value = 1.2
    elif word in MEDIUM:
        value = 0.8
    elif word in TYPES:
        value = 0.5
    elif word in WEAK:
        value = 0.2
    else:
        return carry, 0.0
    if at_line_start(prefix):
        value *= LINE_START_BOOST
    return carry, value

