LEADING_SPACE = {False: -0.00167, True: 0.00057}
TOKEN_LENGTH = {0: 0.00121, 1: 0.00179, 2: 0.00075, 3: -0.00187, 4: -0.00298}
SPECIAL_MARKERS = {"<|im_start|>", "<|im_end|>", "<|endoftext|>"}


def token_class(token):
    word = token.strip()
    if not word:
        return "space"
    if word in SPECIAL_MARKERS:
        return "marker"
    if "\ufffd" in token:
        return "replacement"
    if word.isascii() and word.isdigit():
        return "digit"
    if word.isascii() and word.isalpha():
        if word.islower():
            return "lower"
        if word.isupper():
            return "upper"
        return "mixedcase"
    if word.isascii() and all(not c.isalnum() for c in word):
        return "punct"

    scripts = set()
    for char in word:
        code = ord(char)
        if char.isascii():
            scripts.add("latin")
        elif 0x4E00 <= code <= 0x9FFF:
            scripts.add("cjk")
        elif 0x3040 <= code <= 0x30FF:
            scripts.add("kana")
        elif 0xAC00 <= code <= 0xD7AF:
            scripts.add("hangul")
        elif 0x0600 <= code <= 0x06FF:
            scripts.add("arabic")
        elif 0x0400 <= code <= 0x052F:
            scripts.add("cyrillic")
        else:
            scripts.add("other")
    if len(scripts) == 1:
        return next(iter(scripts))
    return "mixed"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = token_class(prefix.token_strings[-2])
    else:
        previous = "start"
    length = min(len(token.strip()), 4)
    value = (
        CURRENT.get(token_class(token), 0.0)
        + PREVIOUS.get(previous, 0.0)
        + LEADING_SPACE[token.startswith(" ")]
        + TOKEN_LENGTH[length]
    )
    return None, float(value)

