"""Approximate a spelling-and-syntax detector for conditional clause markers.

Training examples concentrate on 'if', so it gets the strongest response,
particularly when capitalized, tabbed or starting a code line. Lowercase
'if' after question words or 'only/even/as' gets a weaker response. Related
connectives, translated markers and example phrases get smaller responses;
'while' can be negative. End-of-text has a separate positive response.

These are local lexical rules, not a parser or a semantic judgment about
whether a sentence really is conditional. Unrecognized tokens return zero.
Keep only 160 recent characters, resetting at each new document.
"""
import re

READS = ()

# Lowercase / capitalized responses for familiar clause markers.
MARKERS = {
    'unless': (1.1, 1.4), 'otherwise': (0.96, 1.34),
    'although': (0.73, 0.9), 'though': (0.68, 0.68),
    'since': (0.33, 0.61), 'given': (0.25, 0.74),
    'depending': (0.95, 1.4), 'once': (0.36, 0.6),
    'when': (-0.02, 0.32), 'while': (-0.39, 0.0),
    'suppose': (0.4, 0.4), 'except': (0.25, 0.25),
    # Russian, German, Romance-language and Vietnamese 'if'.
    'если': (1.4, 1.9), 'wenn': (1.3, 1.9),
    'si': (0.57, 1.2), 'nếu': (1.3, 1.8),
}
QUESTION_VERBS = {
    'see', 'know', 'knows', 'knew', 'check', 'checked', 'checking',
    'determine', 'ask', 'asked', 'wonder', 'wondering', 'assess',
    'test', 'testing', 'verify', 'decide', 'tell', 'sure',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    word = token.strip()
    plain = word.strip('"\'“”().;_#—-')
    lower = plain.lower()
    words = re.findall(r'[a-z]+', before.lower())
    previous = words[-1] if words else ''
    line = before.rsplit('\n', 1)[-1]
    line_start = bool(re.fullmatch(r'[\s\d+\-]*', line))
    code = any(c in before[-100:] for c in '{};')
    value = 0.0
    if token == '<|endoftext|>':
        value = 1.15
    elif lower == 'if':
        if plain == 'If':
            value = 4.02
        elif plain == 'IF':
            value = 3.75
        elif '\t' in token:
            value = 5.0
        elif previous in {'only', 'even', 'as'}:
            value = 1.8 if previous == 'as' else 1.37
        elif previous in QUESTION_VERBS:
            value = 2.4 if previous.startswith('check') else 2.1
            if previous == 'see':
                value = 1.75
        elif line_start:
            value = 4.25
        elif before.endswith(('\\n', '\\t')):
            value = 4.05
        elif token == 'if':
            value = 2.9 if before and before[-1].isalpha() else 4.2
        elif previous in {'else', 'return'}:
            value = 4.15
        elif code:
            value = 3.55
        elif previous in {'and', 'or', 'but'}:
            value = 3.25
        elif previous in {'so', 'because'}:
            value = 2.7
        else:
            value = 2.95
    elif lower in {'elif', 'elseif', 'ifdef', 'ifndef', 'endif'}:
        value = {'elif': 3.75, 'elseif': 3.75, 'ifdef': 4.2,
                 'ifndef': 2.2, 'endif': 1.1}[lower]
    elif lower == 'else':
        value = 1.3 if line_start or code else 0.6
        if previous in {'someone', 'something', 'anyone', 'anything',
                        'everyone', 'everything', 'somewhere', 'anywhere'}:
            value = 0.3
    elif '如果' in word:
        value = 2.75 if word == '如果' else 3.3
    elif word.startswith('若'):
        value = 1.9
    elif lower in MARKERS:
        value = MARKERS[lower][plain[:1].isupper()]
    elif lower == 'for':
        value = 0.48 if plain == 'For' else 0.05
        if line_start or code or '\t' in token:
            value = 0.4
    elif lower in {'example', 'instance'} and previous == 'for':
        value = 1.0
    elif token.lower().startswith('.g') and previous == 'e':
        value = 0.65
    elif (before + token).lower().endswith('suppose'):
        value = 0.4
    elif (before + token).lower().endswith('если'):
        value = 1.9
    elif lower == 'catch':
        value = 0.35
    return (doc, (before + token)[-160:]), float(value)

