"""Draft 2: graded by what comes before the word."""
import re

READS = ()
# "if" and its equivalents in other languages
IF_WORDS = {"if", "elif", "如果", "若", "若是", "要是", "если", "wenn", "nếu"}
# words that take a conditional clause, weaker than "if" itself
WEAK_WORDS = {"else", "unless", "otherwise", "though", "although", "since", "given", "depending", "assuming"}
# "if" that completes a phrase ("even if", "as if", "see if") rather than opening a clause
PHRASE_BEFORE_IF = {"even", "only", "as", "see", "know", "sure", "determine", "check", "is"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    bare = word.strip().lower()
    if bare in IF_WORDS:
        before = prefix.token_strings[-2] if len(prefix) > 1 else "\n"
        if before.strip() == "" or re.fullmatch(r"\W+", before.strip()):
            # the word opens a new clause or a code line: after punctuation, a newline or indentation
            return None, 4.0
        if before.strip().lower() in PHRASE_BEFORE_IF:
            return None, 1.5
        return None, 2.8
    if bare in WEAK_WORDS or word == "<|endoftext|>":
        return None, 1.1
    return None, 0.0

