DESCRIPTORS_HIGH = set('''
valuable dangerous influential profitable prestigious harmless majestic
tasty juicy nutritious ominous
'''.split())
DESCRIPTORS_MEDIUM = set('''
delicious beneficial controversial informative expensive impressive
uncomfortable unnecessary responsible comfortable reliable interesting
