ENDINGS = {
    'ful': 5.7, 'fully': 4.85, 'fulness': 3.2,
    'less': 1.45, 'lessly': 2.2, 'ious': 2.05, 'iously': 1.7,
    'ous': 0.8, 'ously': 1.1, 'uous': 1.0,
    'able': 0.7, 'ably': 0.85, 'ible': 0.4, 'ibly': 0.7,
    'ently': 0.8, 'ately': 0.6, 'ensive': 0.9, 'ential': 0.6,
    'ive': 0.45, 'ively': 0.5, 'ative': 0.35, 'itive': 0.4,
