        return 1.5 if token.strip() == 'Ful' else 2.3
    if word == 'fulness' or word == 'usefulness':
        return 3.0
    if word == 'fullest':
        return 1.7
    if word == 'fully':
        return 0.22
    if word.endswith('ful'):
        if word in FUL_STRONG:
            return 5.5
        if word in FUL_HIGH:
            return 4.2
        if word in FUL_LOW:
            return 2.2
        if word in FUL_WEAK:
            return 0.8
        return 3.25
    if word.endswith('fully'):
        if word in {'hopefully', 'wonderfully'}:
