        if word in {'successfully', 'painfully', 'gracefully'}:
            return 2.0
        return 2.9
    if word in DESCRIPTORS_HIGH:
        return 3.3
    if word in DESCRIPTORS_MEDIUM:
        return 1.85
    if word in DESCRIPTORS:
        return 1.1
    if word in DESCRIPTORS_SMALL:
        return 0.5
