        if token == 'FULL':
            return 3.3
        return 0.96
    if word in {'best', 'most'}:
        return 0.32
    if word in {'的', '無', '无'}:
        return 0.64
    if word == '有':
        return 1.0
    if word in {'しい', 'しく', '的な', '적인'}:
        return 0.9
    if word in {'красив', 'опас', 'удоб', 'эффектив', 'популяр'}:
        return 1.6
    if word == 'успеш':
        return 3.0
    if word in {'有用', '有力', '有趣', '有名', '有毒', '有害', '有益'}:
        return 2.8
    if word in {'有用的', '有趣的', '有名的'}:
        return 3.3
    if word in {'重要', '重要的', '高质量', '厉害', '忠', '积极'}:
        return 1.1
    if word.removesuffix('的') in EAST_ASIAN_QUALITIES:
        return 1.8
    return 0.0


