    # usefulness, value, importance, capability
    "valuable", "important", "effective", "efficient", "responsible", "reliable", "reasonable",
    "relevant", "significant", "crucial", "suitable", "essential", "vital", "capable",
    "appropriate", "accurate", "timely", "convenient", "profitable", "beneficial", "productive",
    "influential", "versatile", "advantageous", "informative", "serious", "indispensable",
    # appeal, character, pleasure
    "beautiful", "lovely", "gorgeous", "delicious", "famous", "interesting", "fascinating",
    "wonderful", "amazing", "stunning", "attractive", "elegant", "impressive", "exciting",
    "comfortable", "friendly", "healthy", "honest", "generous", "proud", "popular", "notable",
    "remarkable", "renowned", "prestigious", "brilliant", "clever", "intelligent", "compelling",
    "thoughtful", "careful", "cautious", "respectful", "supportive", "compassionate",
    # danger, harm, difficulty
    "dangerous", "harmful", "painful", "toxic", "illegal", "expensive", "costly", "controversial",
    "destructive", "hazardous", "difficult", "challenging", "problematic", "terrible", "cruel",
    "vicious", "deadly", "fatal", "severe", "safe", "sensitive",
}

ADVERBS = {"carefully", "successfully", "fully", "beautifully", "efficiently", "gracefully"}

WEAK = {"just", "only", "less", "full", "able", "most", "best", "的", "有"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in NOT_FUL:
        value = WEAK_SCORE if word == "full" else 0.0
    elif word.endswith("ful") or word == "ful":
