    'b': 4.4, 'm': 4.4, 'h': 3.2, 'g': 3.6, 'v': 3.7,
    'p': 3.2, 's': 3.6, 'k': 2.65, 'f': 2.2, 't': 2.45,
    'sk': 2.4, 'j': 2.65, 'st': 1.92, 'dr': 1.9, 'gr': 1.3,
