    'a': 4.4, 'ian': 4.4, 'er': 3.5, 'ing': 3.5, 's': 3.5,
    'as': 3.5, 'us': 3.5, 'e': 2.25, 'o': 2.6, 'i': 3.0,
    'ed': 2.3, 'ard': 3.0,
