"""Layer-0 MLP down-projection component 5479: the "ill" spelling detector.

It is a token-level feature: it reads the current token's spelling and nothing else.
It fires on the letter sequence "ill" (also "ll" after "i" in a few spellings), most
strongly on one-syllable words that end in -ill ("ill", "Bill", "mill", "Hill", "kill",
"pill"), somewhat less on "will" (the most frequent case by far), "still", "till", and
on the contraction "'ll" and the modal "shall". It fires weakly on "should",
"until"/"til", and Roman "II". "ill" that starts or sits inside a longer word
("illustrate", "illegal", "million", "village") fires only weakly. Every other token is 0.

The levels are the mean activation of each group on training text, rounded.
"""
import re

READS = ()

# Words where "ill" is the whole word or a short one-syllable -ill word.
SHORT_ILL = re.compile(r"[bdfghjkmpvw]?ill(s|ed|ing|er|a)?")
STILL_WORDS = {"still", "skill", "skills", "skilled", "stills"}
MID_ILL = re.compile(r"ill(u|e[gn]|umin|ness|ustr)|million|village|oscill|surveill|brilli|fulfil|billion")


def level(token: str) -> float:
    y = token.strip().lower()
    if y in ("'ll", "’ll"):
        return 2.0
    if y == "shall":
        return 1.3
    if y == "should":
        return 0.7
    if y in ("until", "till", "til"):
        return 1.3
    if y in ("ii", "iii"):
        return 0.5
    if "ill" not in y:
        return 0.0
    if y in ("will", "wills"):
        return 2.3
    if y in STILL_WORDS:
        return 1.9
    if MID_ILL.search(y):
        return 1.0
    if SHORT_ILL.fullmatch(y):
        return 3.8
    return 1.9


