phrase context reset at document boundaries. Whitespace has an independent
response based on its space/tab counts. Weaker lexical effects are omitted.
"""
READS = ()


def indentation(text):
    body = text.rstrip('\r\n')
    if not body or any(c not in ' \t' for c in body):
        return 0.0
    tabs = body.count('\t')
    spaces = body.count(' ')
    if tabs == 0:
        if spaces < 17:
            return 0.07 if spaces >= 15 else 0.0
        if spaces < 25:
            return 0.25 + 0.06 * (spaces - 17)
        if spaces <= 35:
            return 0.93
        return 0.72 if spaces <= 44 else 0.15
    if spaces == 0:
        return max(0.0, min(1.2, 0.28 * (tabs - 3)))
    if tabs == 1:
        if spaces == 3:
            return 0.46
        return 0.30 if spaces < 15 else min(1.3, 0.05 * spaces - 0.2)
    return min(1.3, 0.12 * (spaces + tabs))


