    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous_content = same_document and carry[1]
    bare = text.strip().lstrip("._-(/'\"")
    word = bare.lower()
    is_content = word == 'content'

    if is_content:
        value = 6.5
        if text.startswith(' '):
