        elif text.startswith(('_', '/')):
            value = 5.8
        elif text.startswith('('):
            value = 4.7
        elif text.startswith('-'):
            value = 7.2
        elif text.startswith('.'):
            value = 6.9
        elif text.startswith('\t'):
            value = 5.1
    elif word == 'contents':
        value = 4.2 if bare == 'contents' else 3.8
