        value = 5.5 if completes_content else 1.7
    elif word in {'contain', 'contains', 'contained', 'containing'}:
        value = 0.75
    elif previous_content and word == 'of':
        value = 1.88
    elif 'content' in word and any(c.isupper() for c in bare):
        value = 2.8  # compound code identifiers, e.g. contentType
    elif word in {'contenido', 'contenu', 'conteúdo'}:
