The signal is strongest for bare lowercase letters after punctuation.  It is
weaker at line starts, for capitals, and for single-letter variables.  Tokens
which already contain their separator (like ' name' or '.name') stay quiet.
Fresh path roots and command options are stronger than internal separators.
Backslash commands and chat-role markers are not treated as ordinary words.
Alphabetic starts in several other scripts get a weaker response.  URI scheme
names and line-initial import are reduced as special syntax words.
"""
import unicodedata

READS = ()


def latin_letter(c):
    return c.isalpha() and (c.isascii() or 'LATIN' in unicodedata.name(c, ''))


def start_value(word, previous):
    c = previous[-1:]
    if not previous or previous.startswith('<|') or c == '\x00':
        return 0.0
    if latin_letter(c):
        if word.isupper():
            return -0.04
        return 0.0
    single = len(word) == 1
    if not word.islower():
        if c == '\n':
            return -0.06 if single else 0.19 if word.isupper() else 0.02
        if c.isdigit():
            return 0.05 if single else 0.26 if word.isupper() else 0.11
        if word.isupper():
            return 0.17 if single else 0.61
        return 0.32 if word.istitle() else 0.5
    if c == '\\':
        return 0.05 if single else 0.09
    if word in {'http', 'https'}:
        return 0.3 if word == 'http' else 0.2
    if c == '\n':
        if word == 'import':
            return 0.2
        return 0.54 if single else 0.82 if len(word) == 2 else 0.67
    if c.isdigit():
        return 0.68 if single else 0.78
    if previous.endswith('--'):
        return (1.55 if single else 1.9) if previous[:1].isspace() else 1.35
    if c == '/':
        if previous.endswith('</'):
            return 0.6 if single else 0.8
        if previous[:1].isspace():
            return 1.16 if single else 1.95
        return 1.02 if single else 1.27
    if previous.endswith('<<'):
        return 0.9 if single else 1.2
    if c in '(<':
        return 0.64 if single else 0.80
    if c in "'’":
        return 0.65 if single else 1.05
    if c in ':{|&':
        return 1.06 if single else 1.45
    if c in '.-@':
