    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if word.isascii() and word.isalpha():
        value = start_value(word, previous)
        # LaTeX environment names, rather than ordinary brace-delimited words.
        if (previous.endswith('{') and carry is not None
                and carry[2] in {'begin', 'end'} and prefix.position >= 3
                and prefix.document_ids[-4] == doc
                and prefix.token_strings[-4].endswith('\\')):
            value = 0.25
