        script = unicodedata.name(word[-1], '')
        alphabetic_script = any(name in script for name in (
            'LATIN', 'GREEK', 'CYRILLIC', 'ARABIC', 'HEBREW'))
        if (alphabetic_script and previous and previous[-1] != '\x00'
                and not previous[-1:].isalpha()):
            value = 0.3 if word.islower() else 0.1
            if previous.endswith('\n') and not word.islower():
