REACTIONS = set('surprised surprising worry admire admired relax relaxing'.split())
EVALUATION = set('''
    compare compares comparison reflect reflecting reflects reflection
    focus focusing critic critics critique criticism criticize criticised
    weak weaken weakening weakened feedback review
'''.split())
