    'ð': -4.15, 'Ð': -1.55, 'þ': -2.25, ' þ': -2.45,
    'Þ': -2.15, 'ƿ': -2.2, 'æ': -0.22, 'Æ': -0.58,
    '¼': -1.5, '½': -0.4, '¾': -0.3,
}
NAME_ENDINGS = {
