    token = prefix.token_strings[-1]
    value = LETTERS_AND_FRACTIONS.get(token)
    if value is None:
        value = OLD_SCRIPT_PREFIX_TOKENS.get(int(prefix.token_ids[-1]))
    if value is None:
        if any('\u1680' <= c <= '\u16ff' for c in token):
            value = -2.0
