programs.sol:
"""Predict spaces introducing dates or numbered references.

English months are the strongest cues. Foreign months, seasons, numbered
labels, arithmetic signs, and date/year connectors give smaller responses.
Month-name tokens are negative; 'al' after 'et' is positive. Most other tokens
are approximated by zero. Strong spaces weaken with document position, and
nonbreaking spaces are weaker. State resets at document boundaries.
"""
import math
import re

READS = ()
MONTHS = set('January February March April May June July August September '
             'October November December'.split())
ABBREVIATIONS = set('Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec'.split())
FOREIGN_MONTHS = set(('mär abr ago dez '
    'janvier février mars avril mai juin juillet août '
    'septembre octobre novembre décembre '
    'januar februar märz april mai juni juli august september oktober '
    'november dezember '
    'enero febrero marzo abril mayo junio julio agosto septiembre setiembre '
    'octubre noviembre diciembre '
    'janeiro fevereiro março abril maio junho julho agosto setembro outubro '
    'novembro dezembro augustus '
    'января февраля марта апреля мая июня июля августа сентября октября '
    'ноября декабря').split())
NUMBER_LABELS = set('figure table chapter section example page question lemma '
    'lecture lesson route theorem problem exercise class paragraph scenario '
    'assignment day week month year age aged season step case rule grade volume '
    'proposition article algorithm part version '
    'verse scene episode highway suite form exhibit option item solution '
    'graph box study claim act level room title exam homework tutorial'.split())
TECHNICAL_LABELS = set('line lines test code error equation index unit '
                       'python windows iso ph'.split())
MONTH_PATTERN = '|'.join(sorted(MONTHS | ABBREVIATIONS))
DATE_COMMA = re.compile(r'(?:' + MONTH_PATTERN + r')\.?\s+\d{1,2}'
                        r'(?:st|nd|rd|th)?,$')
MONTH_END = re.compile(r'(?:' + MONTH_PATTERN + r')$')
MONTH_LINK = re.compile(r'\b(?:' + MONTH_PATTERN + '|'
    + '|'.join(sorted(FOREIGN_MONTHS)) + r')\s+(?:of|de|to|and)$')
LAST_WORD = re.compile(r'([^\W\d_]+)([.,]?)$')


def space_response(text, previous):
    if not text or previous.isspace():
        return -0.06
    match = LAST_WORD.search(text)
    word, punct = match.groups() if match else ('', '')
    if previous.lstrip() in MONTHS | ABBREVIATIONS:
        word, punct = previous.lstrip(), ''
    lower = word.lower()
    if word in MONTHS | ABBREVIATIONS:
        if punct == ',':
            return 4.7
        if punct == '.':
            return 5.3
        return 7.6 if word in ABBREVIATIONS or word == 'May' else 8.5
    if text.endswith(','):
        return 2.3 if DATE_COMMA.search(text) else 0.05
    if word in {'FIG', 'Fig'}:
        return 5.5
    if lower in {m.lower() for m in MONTHS} | FOREIGN_MONTHS:
        return 4.9
    if word == 'FIGURE':
        return 6.5
    if MONTH_LINK.search(text):
        return 4.5
    if lower in {'spring', 'summer', 'fall', 'winter', 'autumn'}:
        return 3.8
    if lower in {'early', 'late'}:
        return 2.0
    if lower in {'the', 'a', 'an', 'at', 'with', 'is', 'are', 'was',
                 'were', 'and', 'of', 'to', 'for', 'in', 'on', 'by'}:
        return -0.18
    if lower.rstrip('s') in NUMBER_LABELS or lower in NUMBER_LABELS:
        return 4.2 if word[0].isupper() else 2.7
    if lower in TECHNICAL_LABELS:
        return 2.6 if word[0].isupper() and lower != 'test' else 1.8
    if lower == 'copyright' or text.endswith('©'):
        return 4.2
    if punct == '.' or text.endswith('.'):
        if lower in {'pp', 'vol', 'sect', 'sec', 'fig', 'figs'}:
            return 2.5
        if lower in {'no', 'nos', 'nr', 'art', 'eq', 'cir'}:
            return 1.6
        return 0.55
    if text.endswith(('§', '№')):
        return 2.8
    if text.endswith(('=', '>', '<')):
        return 0.8 if previous.startswith(' ') else 0.2
    if previous == '//':
        return 2.3
    if text.endswith(('+', '-', '*', '/', '×', '–')):
        return 0.4
    return 1.2 if previous.lstrip().startswith('#') else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position = '', '', 0
    else:
        _, recent, previous, position = carry
        position += 1
    token = prefix.token_strings[-1]
    word = token.lstrip()
    value = 0.0
    if token in {' ', '\xa0'}:
        value = space_response(recent, previous)
        if value >= 4.0:
            value *= 1.25 - 0.05 * math.log1p(position)
        if token == '\xa0':
            value *= 0.4
    elif word in MONTHS:
        value = -2.9 if position == 0 else -1.1
    elif word in ABBREVIATIONS:
        value = -0.65
    elif token == ' al' and recent.endswith(' et'):
        value = 1.0
    elif token in {' of', ' to'} and MONTH_END.search(recent):
        value = -1.8
    return (doc, (recent + token)[-120:], token, position), float(value)

