             'november december jan feb mar apr jun jul aug sep sept oct nov dec'.split())
MODALS = set('can could will would shall should may might must'.split())
AUXILIARIES = set('is am are was were be been being do does did have has had'.split())
OTHER_FUNCTION_WORDS = set(
    'i you he she it we they me him her us them my your his its our their '
    'to of for from in on at by with without into over under through '
    'about up out after before a an the this that these those all any '
    'some each every no other'.split()
)
CONNECTIVES = set('and or but if as so than then not more most less only very too '
                  'also there here where when what who which why how'.split())
NUMBERS = set('one two three four five six seven eight nine ten eleven twelve '
              'thirteen fourteen fifteen sixteen seventeen eighteen nineteen '
              'twenty thirty forty fifty sixty seventy eighty ninety hundred '
              'thousand million billion'.split())
NUMERIC_LABELS = set('section chapter table figure page example episode version '
                     'route lesson copyright'.split())
KNOWN_WORDS = MODALS | AUXILIARIES | CONNECTIVES | OTHER_FUNCTION_WORDS | NUMBERS


def continuation(previous, token):
    word = previous.strip()
    lower = word.lower()
    if lower not in KNOWN_WORDS or not token:
        return 0.0
    if not (token[0].isalpha() or token[0] == '-'):
        return 0.0
    small = len(word) <= 2
    lowercase = token[0].islower()
    if not previous.startswith(' '):
        if small:
            return -0.16 if word.istitle() and lowercase else -0.02
        if lowercase:
            return -0.52 if word.istitle() else -0.17
        return -0.08
    if word.isupper() and len(word) > 1:
        return -0.04
    if token[0].isupper():
        return -0.10
    # Longer recognizable words and vowel-onset extensions give a stronger cue.
    value = -0.26
    if lower in MODALS:
        value -= 0.44
    elif lower in AUXILIARIES:
        value -= 0.10
    elif lower in CONNECTIVES:
        value -= 0.17
    elif lower in NUMBERS:
        value += 0.18
    if len(word) == 1:
        value += 0.16
    elif len(word) >= 3:
        value -= 0.15
    if token[0] in 'aeiou':
        value -= 0.08
    if word.istitle():
        value += 0.09
    return value


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, month_age = '', 99
    else:
        _, previous, month_age = carry
    month_age += 1
    value = continuation(previous, token)
    if token == ' ':
        previous_word = previous.strip().lower()
        if previous_word in NUMERIC_LABELS or previous_word in {'©', '§'}:
            value = -0.23
        elif previous_word in {',', '.', '.,'}:
            value = -0.04
        if month_age == 1:
            value = -0.89
        elif month_age == 2:
            value = -0.51
        elif month_age <= 6:
            value = -0.35 if previous.strip() == ',' else -0.12
    if token.strip().lower().rstrip('.,') in MONTHS:
        month_age = 0
    return (doc, token, min(month_age, 99)), value

programs.luna:
"""Flag spaces immediately after a written month name, as in a date."""
READS = ()
MONTHS = frozenset((
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
))

def step(carry, prefix, upstream):
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    else:
        previous = ""
    if prefix.token_strings[-1] == " " and previous.strip().lower() in MONTHS:
        return None, -0.75
    return None, 0.0

programs.sol:
"""A lexical room/interior detector, not an indoor-scene classifier.

The largest negative responses are to 'room' and the room character 室.
Kinds of rooms, workplaces, building interiors and furnishings have smaller
responses. These word groups include a few translations. Most tokens give
zero. Nearby words refine bare 'room', and 'of' retains a weaker response
when it follows a recognized word. Strengths are rounded training estimates.
Weaker responses outside this vocabulary are deliberately omitted.
"""

READS = ()

# Specific rooms -> work spaces -> interior structure -> furnishings.
GROUPS = (
    # Rooms and their translated names.
    (4.8, '房间 房間 房间里 教室'),
    (4.3, '室内'),
    (3.8, 'classroom bedroom'),
    (3.1, 'studio 办公室 工作室'),
    (2.7, 'chamber restroom salle phòng 实验室 客厅'),
    (2.2, 'booth bathroom closet courtroom zimmer raum roommate 厅 廳 大厅'),
    (1.9, 'office indoor indoors showroom 宿舍 客房'),
    # Work spaces, dwellings and interior structure.
    (1.4, 'laboratory apartment floor kitchen desk cabinet compartment '
           'hallway upstairs downstairs cupboard basement cafeteria '
           'lab greenhouse cabin lounge balcony chambre sala wohnung 楼 屋 堂'),
    # Furniture, fittings and indoor comfort.
    (1.0, 'seat chair couch sofa furniture shop wheelchair spacious '
           'comfy stadium aisle patio doorway corridor 柜 棚 床 桌 座椅 厨房'),
    (0.8, 'door hall shower outdoor workshop tent gym lobby interior '
           'comfortable comfortably cozy seating toilet トイレ 座'),
    (0.6, 'bed ceiling mattress shelf comfort suite department stairs '
           'house building wall facility shelter accommodation gallery '
           'bench chapel salon shelves 屋顶 部门 门 房屋'),
    (0.3, 'speaker 内 所'),
)
WEIGHTS = {word: -weight for weight, words in GROUPS for word in words.split()}


def lexical(token):
    word = token.strip().lstrip('-._').lower()
    if word.endswith('ies') and word[:-3] + 'y' in WEIGHTS:
        word = word[:-3] + 'y'
    elif word.endswith('s') and word[:-1] in WEIGHTS:
        word = word[:-1]
    if word in {'room', 'rooms'}:
        separated = token.startswith((' ', '-', '.', '_'))
        value = -6.4 if separated else -5.6
        if token.strip() == 'Room' and separated:
            value = -7.2
        if token.strip() in {'ROOM', 'ROOMS'}:
            value = -5.7 if separated else -4.2
        return value
    if word == '(room':
        return -3.4
    if word == '室':
        return -6.4
    if word == '房':
        return -2.5
    if word == '실':
        return -2.5 if token.startswith(' ') else -4.2
    if word.startswith('комнат'):
        return -4.5
    if word.startswith('помещ'):
        return -2.1
    if word.startswith('офис'):
        return -1.2
    if word in {'间', '間'}:
        return -0.9
    if word in WEIGHTS:
        value = WEIGHTS[word]
        # Short unspaced pieces often belong to unrelated longer words.
        if word in {'bed', 'lab'} and not token.startswith(' '):
            value *= 0.2
        return value
    if '室' in word:
        return -2.6
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip().lower()
    value = lexical(token)
    if word in {'room', 'rooms'}:
        if token.startswith(' '):
            if previous in {'the', 'my', 'your', 'his', 'her', 'our',
                            'their', 'same', 'entire', 'dining'}:
                value -= 0.6
            elif previous in {'living', 'to', 'no'}:
                value = -5.7
            elif previous == 'emergency':
                value = -4.8
        elif previous.endswith(('mush', 'ush')):
            value = -3.5
        elif previous in {'b', 'br'}:
            value = -3.8
    elif word in {'studio', 'studios'} and token.strip().startswith('S'):
        value = -0.7 if previous == 'visual' else -2.6
    elif word == 'of' and previous:
        value = 0.35 * lexical(prefix.token_strings[-2])
    return None, float(value)

programs.haiku:
"""Room detector (layer 0 MLP, down_proj component 5496).

The component reads the MLP's hidden state and pushes the residual stream
strongly negative when the current token names an enclosed indoor space. It is
strongest on the word "room" (and its plural, the Chinese 室 for room), weaker on
other kinds of room (bedroom, classroom, studio, 房, 客厅), weaker still on
workplaces and household places (office, lab, kitchen, floor), and slightly
negative on other building and furniture words. Everything else is about zero.
"""

READS = ()

# Tier values: typical activation for each class of word (nats-scale, negative).
ROOM_WORD = -6.3      # "room", "rooms", "室"
ROOM_KIND = -3.0      # other rooms and rooms-within-a-building
WORKPLACE = -1.5      # offices, labs, kitchens, floors, booths
BUILDING = -0.7       # houses, halls, doors, seats, beds, furniture

ROOM_WORDS = {"room", "rooms", "室", "-room", "roomy"}
ROOM_KINDS = {
    "bedroom", "bedrooms", "classroom", "classrooms", "bathroom", "bathrooms",
    "restroom", "showroom", "studio", "studios", "chamber", "房", "客厅", "寝室",
    "客房", "浴室", "厅", "廳", "zimmer", "salle", "실",
}
WORKPLACES = {
    "office", "offices", "办公室", "lab", "labs", "laboratory", "laboratories",
    "实验室", "kitchen", "floor", "floors", "apartment", "apartments", "cabinet",
    "booth", "booths", "closet", "cabin", "cafeteria", "basement", "workshop",
    "lounge", "cellar", "attic", "garage", "stairs", "upstairs", "downstairs", "楼", "屋", "间", "間", "房屋", "房子",
}
BUILDINGS = {
    "house", "houses", "hall", "department", "departments", "door", "doors", "seat",
    "seats", "chair", "chairs", "building", "buildings", "furniture",
    "interior", "interiors", "shower", "ceiling", "walls", "sofa", "couch", "desk",
    "shop", "shops", "indoor", "outdoor", "屋顶", "座", "厅",
}


def _word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    w = _word(prefix.token_strings[-1])
    if w in ROOM_WORDS:
        return carry, ROOM_WORD
    if w in ROOM_KINDS:
        return carry, ROOM_KIND
    if w in WORKPLACES:
        return carry, WORKPLACE
    if w in BUILDINGS:
        return carry, BUILDING
    return carry, 0.0

"""Layer-0 MLP component 5498: a "for / The" token detector.

Strongly negative on the preposition "for" (about -0.6 after a space, about -0.9 when the
word starts a line or is capitalised as "For") and on the sentence-opening word "The"
(about -0.55 with a leading space, -0.7 without). It is also negative on the chat-role
token "assistant" and on "<|endoftext|>". Everything else is near zero.
"""

READS = ()

FOR_SPACED = {" for"}
FOR_OTHER = {"for", "For", " For", "\tfor", "-for"}
THE_SPACED = {" The"}
THE_OTHER = {"The"}
SPECIAL = {"assistant", "<|endoftext|>"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in FOR_SPACED:
        value = -0.6
    elif tok in FOR_OTHER:
        value = -0.9
    elif tok in THE_SPACED:
        value = -0.55
    elif tok in THE_OTHER:
        value = -0.7
    elif tok in SPECIAL:
        value = -0.75
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""Predict sparse negative responses tied to a few recognizable tokens.

The rule gives fixed negative values to 'for', 'For', capitalized 'The',
chat-role and end-of-document markers, and zero to other tokens. It captures
the recurring lexical triggers but not their contextual variation.
"""
READS = ()

LEVELS = {
    "for": -0.67,
    "For": -0.89,
    "The": -0.59,
    "assistant": -0.74,
    "<|endoftext|>": -0.78,
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "assistant":
        previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
        if previous != "<|im_start|>":
            token = ""
    return None, float(LEVELS.get(token, 0.0))

programs.sol:
"""Approximate a detector for vowel-free ASCII letter fragments.

Consonant-only fragments joined across a token boundary get large positive
values. Standalone three-letter clusters get smaller values; familiar English
consonant spellings are weaker. Length, capitalization, and an occasional
final vowel refine the response. Other text is mostly zero. These are spelling
rules with fitted category amplitudes, not a dictionary of token identities.
Only the preceding token is remembered, and documents reset that memory.
"""
import re

READS = ()
VOWELS = frozenset('aeiouy')
ENGLISH_CLUSTERS = frozenset('''
    ch sh th ph wh ck ng gh sch tch str spr scr spl thr shr
    bl br cl cr dr fl fr gl gr pl pr sl sm sn sp st sw tr tw
    sk sc wr kn gn
'''.split())


def letter_tail(text):
    match = re.search(r'[A-Za-z]+$', text)
    return match.group(0) if match else ''


def has_vowel(text):
    return any(c in VOWELS for c in text.lower())


def response(current, previous, joined, first):
    if not current:
        return 0.0
    n = len(current)
    vowels = has_vowel(current)
    cluster = current.lower() in ENGLISH_CLUSTERS
    prev_consonant = bool(previous and previous[-1].lower() not in VOWELS)
    if not joined:
        return 0.53 if n == 3 and not vowels and not cluster else 0.0
    if vowels:
        if prev_consonant and current[0].lower() not in VOWELS:
            if n == 2 and not has_vowel(previous):
                return 0.71 if current.isupper() else 0.37
            if current.isupper() and current[-1].lower() in VOWELS:
                return 0.27
        return 0.0
    if not prev_consonant:
        if first:
            return 0.68
        if cluster:
            return 0.0
        return 0.46 if n == 3 else 0.12 if n == 2 else 0.0
    if has_vowel(previous):
        if len(previous) <= 2:
            return 0.14 if cluster else 0.40
        return 0.11
    if n == 1:
        if len(previous) == 1:
            return 0.79
        return 0.90 if current.isupper() != previous.isupper() else 1.45
    if cluster:
        return 1.05
    if current.islower():
        return 1.53
    capitals = sum(c.isupper() for c in previous)
    return 1.18 if capitals <= 1 else 1.51


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else letter_tail(carry[1])
    current = letter_tail(token.strip())
    joined = bool(token and token[0].isascii() and token[0].isalpha())
    value = response(current, previous, joined, first)
    return (doc, token), value

programs.haiku:
"""Consonant-only letter fragments of a longer word, identifier or acronym.

Component layers.0.mlp.down_proj:5499 fires on a short piece of a split word that has
no vowel and is written in letters only, with no leading space: "fm" in "gvfm", "DF"
in "STDF", "bs" in "h.bs", "tp" in "aiosmtpd", the "d" in "aiosmtpd", "K" in "PBKDF2".
Examples of what it ignores: ordinary words and pronounceable pieces ("the", "ing",
"th", "st"), anything with a vowel, digits, punctuation, and the "n" of a "\\n" escape.

The program predicts:
- 0 unless the token is a 1-3 letter ASCII fragment with no vowel (a, e, i, o, u, y)
  and no leading space, and the previous token does not end in a backslash;
- a larger value when that fragment continues a word (the previous token is letters),
  and larger again for capitals and for two or more letters;
- a small value otherwise.

Scores on 6144 training rows (about 3.1M tokens): variance explained about 0.17. A
per-token lookup table gets about 0.31 out of sample, so most of the remainder is
token-specific and not captured by the rule.
"""

VOWELS = set("aeiouyAEIOUY")


def _is_fragment(token: str) -> bool:
    """1-3 ASCII letters, no vowel, no leading space."""
    return 0 < len(token) <= 3 and token.isascii() and token.isalpha() and not (set(token) & VOWELS)


def _is_word(text: str) -> bool:
    """Letters only (leading space allowed): a word or a word piece."""
    text = text.strip()
    return len(text) > 0 and text.isascii() and text.isalpha()


READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not _is_fragment(token):
        return carry, 0.0
    previous = ""
    if len(prefix) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    if previous.endswith("\\"):
        return carry, 0.0
    if _is_word(previous):
        return carry, 0.3 + 0.3 * token.isupper() + 0.1 * (len(token) >= 2)
    return carry, 0.1

programs.luna:
"""Give faint guesses to compact letter groups and capitalized fragments."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letters = [char for char in token if char.isalpha()]
    if not letters:
        return None, 0.0

    uppercase = sum(char.isupper() for char in letters)
    starts_with_space = token[0].isspace()
    if uppercase:
        if uppercase == len(letters) and len(letters) <= 4:
            guess = 0.0375
        else:
            guess = 0.0175
    elif len(letters) == 1:
        guess = 0.01 if starts_with_space else 0.02
    elif len(letters) <= 3:
        guess = 0.006 if starts_with_space else 0.0115
    else:
        guess = 0.0
    return None, guess

programs.sol:
"""A token-local detector of punctuation opening multiline content.

Opening delimiters fused with a newline give the largest negative response.
Colons, comments, and line-continuation operators give weaker responses.
Weaker rules cover delimiters followed by backslashes and the <think>
block opener. Other tokens are quiet. No preceding context is used.
"""
READS = ()
CONTINUATIONS = {'+', '-', '*', '|', '&', '^', '=', '=>', ':=', '\\'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    value = 0.0
    if '\n' in token:
        if mark.endswith(('(', '([')):
            value = -3.8
        elif mark.endswith('['):
            value = -3.2
        elif mark.endswith('<'):
            value = -2.2
        elif mark.endswith('({'):
            value = -1.9
        elif mark.endswith('{'):
            value = -1.15
        elif mark.startswith('/*') and not mark.endswith('*/'):
            value = -1.05
        elif mark.endswith((':', '：')) and not mark.endswith('):'):
            value = -0.36 if token.count('\n') > 1 else -0.25
        elif mark == '/':
            value = -0.7
        elif mark in {'&&', '||'}:
            value = -1.2
        elif mark in CONTINUATIONS:
            value = -0.6
        elif mark.endswith(('">', "'>")):
            value = -0.5
    elif mark.endswith(('(\\', '[\\')):
        value = -0.5
    elif mark.endswith('{\\'):
        value = -0.18
    elif mark == '<think>':
        value = -0.28
    return None, value

programs.luna:
"""Predict negative responses to line breaks after unfinished code syntax."""
READS = ()

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if not s.endswith(("\n", "\r")):
        return None, 0.0
    line = s.rstrip("\r\n").rstrip(" \t")
    if line.endswith(("(", "[")):
        return None, -3.5
    if line.endswith("{"):
        return None, -1.1
    if line.endswith(("/*", "/**")):
        return None, -1.0
    if line.endswith("/"):
        return None, -0.7
    if line.endswith(":"):
        return None, -0.34
    if line.endswith(">"):
        return None, -0.5
    return None, 0.0
